peration_id":"p4_get_gateway_v3_health_lockers","method":"GET","path":"/api/hiecm/gateway/v3/health-lockers","summary":"This API is invoked to fetch the record with health locker enabled provider details.","tag":"abdm-gateway","module":"p4"},{"operation_id":"record-share_get_patient_record_v3_audit_history","method":"GET","path":"/api/hiecm/patient-record/v3/audit-history","summary":"List the record sharing history of the signed in user.","tag":"abdm-record-share-phr","module":"record-share"},{"operation_id":"record-share_post_patient_record_v3_notify","method":"POST","path":"/api/hiecm/patient-record/v3/notify","summary":"Notify the HIE-CM of the transfer status, once, after the data transfer completes.","tag":"abdm-record-share-phr","module":"record-share"},{"operation_id":"record-share_post_patient_record_v3_on_share","method":"POST","path":"/api/hiecm/patient-record/v3/on-share","summary":"Reply to a share request with the data push URL and the encryption key.","tag":"abdm-record-share-hiu","module":"record-share"},{"operation_id":"record-share_post_patient_record_v3_share","method":"POST","path":"/api/hiecm/patient-record/v3/share","summary":"Share a patient's records with the HIU whose QR code was scanned.","tag":"abdm-record-share-phr","module":"record-share"}]}
